/* Board Game renderer – warp/hazard, Avoid/Zone, swap item */
#include "game.h"
#include "logger.h"
#include <tiny3d.h>
#include <stdio.h>
#include <math.h>
#include <string.h>

#define SCR_W 848.0f
#define SCR_H 512.0f

static void draw_rect(float x, float y, float w, float h, u32 rgba) {
    tiny3d_SetPolygon(TINY3D_QUADS);
    tiny3d_VertexPos(x,y,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x+w,y,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x+w,y+h,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x,y+h,0); tiny3d_VertexColor(rgba);
    tiny3d_End();
}
static void draw_circle(float cx, float cy, float r, u32 rgba, int segs) {
    int i; if (segs < 6) segs = 6;
    tiny3d_SetPolygon(TINY3D_TRIANGLE_FAN);
    tiny3d_VertexPos(cx,cy,0); tiny3d_VertexColor(rgba);
    for (i=0;i<=segs;++i) {
        float a=(float)i/(float)segs*6.2831853f;
        tiny3d_VertexPos(cx+cosf(a)*r, cy+sinf(a)*r, 0); tiny3d_VertexColor(rgba);
    }
    tiny3d_End();
}
static void draw_line(float x1,float y1,float x2,float y2,float th,u32 rgba) {
    float dx=x2-x1,dy=y2-y1,len=sqrtf(dx*dx+dy*dy),nx,ny;
    if (len<0.5f) return; nx=-dy/len*(th*0.5f); ny=dx/len*(th*0.5f);
    tiny3d_SetPolygon(TINY3D_QUADS);
    tiny3d_VertexPos(x1+nx,y1+ny,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x2+nx,y2+ny,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x2-nx,y2-ny,0); tiny3d_VertexColor(rgba);
    tiny3d_VertexPos(x1-nx,y1-ny,0); tiny3d_VertexColor(rgba);
    tiny3d_End();
}
static u32 player_color(int i){static const u32 c[]={0xFFE74C3C,0xFF3498DB,0xFF2ECC71,0xFFF1C40F};return c[i&3];}
static u32 player_color_dark(int i){static const u32 c[]={0xFFC0392B,0xFF2980B9,0xFF27AE60,0xFFD4AC0D};return c[i&3];}
static const unsigned char FONT3x5[][5]={{0x7,0x5,0x5,0x5,0x7},{0x2,0x6,0x2,0x2,0x7},{0x7,0x1,0x7,0x4,0x7},{0x7,0x1,0x7,0x1,0x7},{0x5,0x5,0x7,0x1,0x1},{0x7,0x4,0x7,0x1,0x7},{0x7,0x4,0x7,0x5,0x7},{0x7,0x1,0x1,0x1,0x1},{0x7,0x5,0x7,0x5,0x7},{0x7,0x5,0x7,0x1,0x7}};
static void draw_digit(float x,float y,int d,float s,u32 rgba){int r,c;if(d<0||d>9)return;for(r=0;r<5;++r){unsigned char b=FONT3x5[d][r];for(c=0;c<3;++c)if(b&(1<<(2-c)))draw_rect(x+c*s,y+r*s,s,s,rgba);}}
static void draw_number(float x,float y,int value,float s,u32 rgba){char buf[12];int i,n,neg=0;if(value<0){neg=1;value=-value;}n=snprintf(buf,sizeof(buf),"%d",value);if(neg){draw_rect(x,y+s*2,s*2,s,rgba);x+=s*3;}for(i=0;i<n;++i)draw_digit(x+i*(s*4),y,buf[i]-'0',s,rgba);}
static void draw_label_P(float x,float y,float s,u32 c){draw_rect(x,y,s,s*5,c);draw_rect(x,y,s*3,s,c);draw_rect(x+s*2,y,s,s*3,c);draw_rect(x,y+s*2,s*3,s,c);}
static void draw_label_star(float x,float y,float r,u32 c){draw_rect(x-r*0.2f,y-r,r*0.4f,r*2,c);draw_rect(x-r,y-r*0.2f,r*2,r*0.4f,c);draw_circle(x,y,r*0.45f,c,8);}
static void draw_item_icon(float x,float y,ItemType it,int sel){u32 bg=sel?0xFFF1C40F:0xFF34495E;draw_rect(x,y,28,28,bg);draw_rect(x+2,y+2,24,24,0xFF1C2833);switch(it){case ITEM_DOUBLE_DICE:draw_rect(x+6,y+6,8,8,0xFFFFFFFF);draw_rect(x+14,y+14,8,8,0xFFFFFFFF);break;case ITEM_BOOST:draw_rect(x+12,y+5,4,18,0xFF2ECC71);draw_rect(x+6,y+12,16,4,0xFF2ECC71);break;case ITEM_STEAL:draw_circle(x+14,y+14,8,0xFFE74C3C,8);break;case ITEM_SHIELD:draw_circle(x+14,y+14,9,0xFF3498DB,8);draw_circle(x+14,y+14,5,0xFF1C2833,6);break;case ITEM_SWAP:draw_rect(x+6,y+8,6,12,0xFFF1C40F);draw_rect(x+16,y+8,6,12,0xFFE74C3C);draw_rect(x+8,y+12,12,4,0xFFFFFFFF);break;default:break;}}
static void space_style(SpaceType t,bool revealed,u32 *col,float *r){*r=14;*col=0xFF95A5A6;switch(t){case SPACE_PLUS_COIN:*col=0xFF27AE60;*r=15;break;case SPACE_MINUS_COIN:*col=0xFFC0392B;*r=15;break;case SPACE_EVENT:*col=0xFF8E44AD;*r=15;break;case SPACE_SHOP:*col=0xFFD35400;*r=17;break;case SPACE_STAR:*col=0xFFF39C12;*r=18;break;case SPACE_HIDDEN_COIN:case SPACE_HIDDEN_STAR:*col=revealed?0xFF16A085:0xFF7F8C8D;break;case SPACE_WARP:*col=0xFF1ABC9C;*r=16;break;case SPACE_HAZARD:*col=0xFFE67E22;*r=16;break;default:break;}}
static void draw_space_icon(float x,float y,SpaceType t,float r){switch(t){case SPACE_PLUS_COIN:draw_rect(x-2,y-r*0.5f,4,r,0xFFFFFFFF);draw_rect(x-r*0.5f,y-2,r,4,0xFFFFFFFF);break;case SPACE_MINUS_COIN:draw_rect(x-r*0.5f,y-2,r,4,0xFFFFFFFF);break;case SPACE_STAR:draw_label_star(x,y,r*0.55f,0xFFFFFFFF);break;case SPACE_SHOP:draw_rect(x-r*0.4f,y-r*0.3f,r*0.8f,r*0.6f,0xFFFFFFFF);draw_rect(x-r*0.25f,y-r*0.5f,r*0.5f,r*0.25f,0xFFFFFFFF);break;case SPACE_EVENT:draw_circle(x,y,r*0.35f,0xFFFFFFFF,8);break;case SPACE_WARP:draw_circle(x,y,r*0.4f,0xFFFFFFFF,8);draw_circle(x,y,r*0.18f,0xFF1ABC9C,6);break;case SPACE_HAZARD:draw_rect(x-2,y-r*0.45f,4,r*0.9f,0xFFFFFFFF);draw_rect(x-r*0.2f,y+r*0.25f,r*0.4f,r*0.2f,0xFFFFFFFF);break;default:break;}}
static void node_screen(const BoardNode *n,float ox,float oy,float sx,float sy,float *ox2,float *oy2){*ox2=ox+n->x*sx;*oy2=oy+n->y*sy;}
static void draw_contact_shadow(float x,float y,float scale){float sx=14.0f*scale;draw_circle(x,y+12,sx*0.55f,0x66000000,10);draw_circle(x,y+12,sx*0.35f,0x44000000,8);}
static void draw_character(float x,float y,int ci,int facing,float bounce,int idle,float shadow_s){u32 body=player_color(ci),dark=player_color_dark(ci);float by=y-bounce,ex=facing>=0?3.f:-3.f;draw_contact_shadow(x,y,shadow_s>0.1f?shadow_s:0.7f);draw_rect(x-8,by+6,6,10,dark);draw_rect(x+2,by+6,6,10,dark);draw_circle(x,by-2,14,body,12);draw_circle(x,by+2,7,0x33FFFFFF,8);draw_circle(x,by-18,12,body,10);draw_circle(x-4+ex*0.3f,by-20,3.2f,0xFFFFFFFF,6);draw_circle(x+4+ex*0.3f,by-20,3.2f,0xFFFFFFFF,6);draw_circle(x-4+ex,by-20,1.6f,0xFF1A1A1A,6);draw_circle(x+4+ex,by-20,1.6f,0xFF1A1A1A,6);draw_rect(x-4,by-12,8,2,0xFF1A1A1A);draw_circle(x+10,by-((idle/20)&1?28:26),3.5f,dark,6);}
static void draw_board(GameContext *g){Board *b=g->board;float ox=40,oy=70,sx=640,sy=360;int i,j;Player *cur=&g->players[g->current_player];draw_rect(ox-14,oy-10,sx+28,sy+28,0xFF080C14);draw_rect(ox-12,oy-12,sx+24,sy+24,0xFF0D1520);draw_rect(ox-8,oy-8,sx+16,sy+16,0xFF1A2332);draw_rect(ox-4,oy-4,sx+8,sy+8,0xFF243447);draw_rect(ox-2,oy-2,sx+4,sy+4,0xFF2C3E50);draw_rect(ox,oy,sx,3,0x33FFFFFF);for(i=0;i<b->node_count;++i){BoardNode *n=&b->nodes[i];float x1,y1;node_screen(n,ox,oy,sx,sy,&x1,&y1);for(j=0;j<n->next_count;++j){BoardNode *m=&b->nodes[n->next[j]];float x2,y2;int hl=0;node_screen(m,ox,oy,sx,sy,&x2,&y2);if(g->state==STATE_BRANCH&&i==cur->node)hl=(j==g->branch_choice)?2:1;if(hl==2){draw_line(x1,y1,x2,y2,10,0xFFF1C40F);draw_line(x1,y1,x2,y2,4,0xFFFFFFFF);}else if(hl==1)draw_line(x1,y1,x2,y2,7,0xFF7F8C8D);else{draw_line(x1,y1+2,x2,y2+2,8,0x55000000);draw_line(x1,y1,x2,y2,7,0xFF34495E);draw_line(x1,y1,x2,y2,3,0xFFBDC3C7);}}}for(i=0;i<b->node_count;++i){BoardNode *n=&b->nodes[i];float x,y,r;u32 col;node_screen(n,ox,oy,sx,sy,&x,&y);space_style(n->type,n->hidden_revealed,&col,&r);if(g->land_flash>0&&i==cur->node)draw_circle(x,y,(r+8)*(1+0.25f*sinf(g->anim_t*14)),0x88FFFFFF,10);draw_circle(x+2,y+3,r+2,0x88000000,10);draw_circle(x,y,r+2.5f,0xFF1C2833,10);draw_circle(x,y,r,col,10);draw_circle(x-r*0.28f,y-r*0.28f,r*0.32f,0x44FFFFFF,8);draw_space_icon(x,y,n->type,r);}}
static void draw_tokens(GameContext *g){int i;for(i=0;i<g->player_count;++i){Player *p=&g->players[i];float bounce=0;if(p->celebrating)bounce=fabsf(sinf(g->anim_t*10))*16;else if(i==g->current_player&&p->hop_t>=1)bounce=fabsf(sinf(g->anim_t*4))*4;draw_character(p->disp_x,p->disp_y,p->color,1,bounce,(int)g->frame+i*7,p->shadow_s);if(p->shielded)draw_circle(p->disp_x,p->disp_y-8,22,0x443498DB,10);}}
static void draw_die_face(float cx,float cy,float size,int value,u32 body,u32 pip){float h=size*0.5f,pr=size*0.09f,o=size*0.22f;int v=value;if(v<1)v=1;if(v>6)v=6;draw_rect(cx-h+4,cy+h-2,size-4,6,0x55000000);draw_rect(cx-h,cy-h,size,size,0xFF1A1A1A);draw_rect(cx-h+3,cy-h+3,size-6,size-6,body);draw_rect(cx-h+3,cy-h+3,size-6,4,0x33FFFFFF);if(v==1||v==3||v==5)draw_circle(cx,cy,pr,pip,8);if(v>=2){draw_circle(cx-o,cy-o,pr,pip,8);draw_circle(cx+o,cy+o,pr,pip,8);}if(v>=4){draw_circle(cx+o,cy-o,pr,pip,8);draw_circle(cx-o,cy+o,pr,pip,8);}if(v==6){draw_circle(cx-o,cy,pr,pip,8);draw_circle(cx+o,cy,pr,pip,8);}}
static void draw_dice(GameContext *g){float cx=760,cy=110,pulse=1+0.06f*sinf(g->anim_t*8);if(g->state==STATE_DICE_ROLL||g->state==STATE_ITEM){int spin=1+((int)(g->anim_t*12)%6);draw_die_face(cx,cy,52*pulse,spin,0xFFFFFFFF,0xFF1A1A1A);if(g->double_dice)draw_die_face(cx-50,cy+10,40*pulse,spin,0xFFFFF8E7,0xFF1A1A1A);}else if(g->dice_value>0&&(g->state==STATE_MOVE||g->state==STATE_BRANCH||g->state==STATE_LAND||g->state==STATE_SHOP)){draw_die_face(cx,cy,48,g->dice_value,0xFFFFF8E7,0xFF1A1A1A);if(g->dice_value2>0)draw_die_face(cx-50,cy+8,40,g->dice_value2,0xFFFFF8E7,0xFF1A1A1A);draw_number(cx-8,cy+36,g->move_remaining,3,0xFF3498DB);}}
static void draw_popup(GameContext *g){u32 col;if(!g->popup.active)return;switch(g->popup.kind){case 0:col=0xFF2ECC71;break;case 1:col=0xFFF1C40F;break;case 2:col=0xFFE74C3C;break;case 3:col=0xFFE67E22;break;case 5:col=0xFF3498DB;break;default:col=0xFF9B59B6;break;}if(g->popup.kind==1)draw_label_star(g->popup.x,g->popup.y,12,col);else draw_number(g->popup.x-10,g->popup.y,g->popup.value,4,col);}
static void draw_fx(GameContext *g){int i;for(i=0;i<MAX_FX;++i)if(g->fx[i].active)draw_rect(g->fx[i].x,g->fx[i].y,4,4,g->fx[i].color);}
static void draw_hud(GameContext *g){int i,j;draw_rect(0,0,SCR_W,56,0xF00A0E14);draw_rect(0,56,SCR_W,3,g->team_mode?0xFFE67E22:0xFF3498DB);for(i=0;i<g->player_count;++i){Player *p=&g->players[i];float bx=16+i*200;draw_rect(bx,6,188,44,0xFF1C2833);if(i==g->current_player)draw_rect(bx,6,188,44,0x553498DB);if(g->team_mode)draw_rect(bx,6,6,44,p->team==0?0xFFE74C3C:0xFF3498DB);draw_circle(bx+22,28,14,player_color(p->color),10);draw_label_P(bx+42,12,3,0xFFFFFFFF);draw_digit(bx+56,12,i+1,3,0xFFFFFFFF);draw_label_star(bx+90,18,7,0xFFF1C40F);draw_number(bx+102,12,p->stars,3,0xFFF1C40F);draw_circle(bx+140,20,7,0xFFF39C12,8);draw_number(bx+152,12,p->coins,3,0xFFF39C12);if(i==g->current_player)for(j=0;j<p->item_count;++j)draw_item_icon(bx+42+j*32,50,p->items[j],0);}{float prog=g->max_rounds>0?(float)g->round/g->max_rounds:0;if(prog>1)prog=1;draw_rect(40,490,640,12,0xFF1C2833);draw_rect(40,490,640*prog,12,0xFF3498DB);draw_number(690,488,g->round,2.5f,0xFFFFFFFF);}}
static void draw_item_panel(GameContext *g){Player *p=&g->players[g->current_player];int i;draw_rect(260,180,328,120,0xEE1A2332);draw_rect(270,190,308,100,0xFF243447);for(i=0;i<p->item_count;++i)draw_item_icon(290+i*50,220,p->items[i],i==g->item_cursor);draw_rect(290+p->item_count*50,220,28,28,g->item_cursor>=p->item_count?0xFF7F8C8D:0xFF2C3E50);}
static void draw_shop_panel(GameContext *g){Player *p=&g->players[g->current_player];int c=g->item_cursor%3;draw_rect(220,150,408,200,0xEE1A2332);draw_rect(230,160,388,180,0xFF243447);draw_rect(250,180,100,80,c==0?0xFFF1C40F:0xFF1C2833);draw_label_star(300,210,14,0xFFF1C40F);draw_number(280,240,20,3,0xFFF39C12);draw_rect(370,180,100,80,c==1?0xFF9B59B6:0xFF1C2833);draw_circle(420,210,14,0xFF9B59B6,8);draw_number(400,240,8,3,0xFFF39C12);draw_rect(490,180,100,80,c==2?0xFF7F8C8D:0xFF1C2833);draw_number(250,280,p->coins,3.5f,0xFFF39C12);}
static void draw_title(GameContext *g){float bob=sinf(g->anim_t*2.5f)*8;draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_rect(120,100,608,280,0xFF162033);draw_rect(140,120,568,240,0xFF1B2838);draw_character(220,300+bob,0,1,fabsf(sinf(g->anim_t*5))*10,(int)g->frame,1);draw_character(340,300-bob,1,1,fabsf(sinf(g->anim_t*5+1))*10,(int)g->frame,1);draw_character(460,300+bob*0.7f,2,-1,fabsf(sinf(g->anim_t*5+2))*10,(int)g->frame,1);draw_character(580,300-bob*0.7f,3,-1,fabsf(sinf(g->anim_t*5+3))*10,(int)g->frame,1);draw_label_star(424,160+bob*0.3f,18+4*sinf(g->anim_t*3),0xFFF1C40F);if(((int)(g->anim_t*2))&1)draw_rect(300,400,248,14,0xFF2ECC71);}
static void draw_results(GameContext *g){int best=0,i,ts[2]={0,0};draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_rect(180,80,488,340,0xFF162033);if(g->team_mode&&g->player_count>=4){for(i=0;i<g->player_count;++i)ts[g->players[i].team]+=g->players[i].stars;best=ts[1]>ts[0]?1:0;draw_character(360,280,best==0?0:2,1,fabsf(sinf(g->anim_t*6))*14,(int)g->frame,1);draw_character(480,280,best==0?1:3,1,fabsf(sinf(g->anim_t*6+1))*14,(int)g->frame,1);draw_number(400,160,ts[best],5,0xFFF1C40F);}else{for(i=1;i<g->player_count;++i)if(g->players[i].stars>g->players[best].stars||(g->players[i].stars==g->players[best].stars&&g->players[i].coins>g->players[best].coins))best=i;draw_character(424,280,g->players[best].color,1,fabsf(sinf(g->anim_t*6))*14,(int)g->frame,1);draw_label_star(424,140,22,0xFFF1C40F);draw_number(400,170,g->players[best].stars,4,0xFFF1C40F);draw_number(400,210,g->players[best].coins,3,0xFFF39C12);}}
static void draw_howto_bar(MiniGameType t){draw_rect(100,430,648,36,0xEE0D1117);if(t==MG_MASH){draw_rect(140,440,20,16,0xFF2ECC71);draw_rect(200,438,8,20,0xFFFFFFFF);draw_rect(194,438,20,8,0xFFFFFFFF);}else if(t==MG_TIMING){draw_rect(140,442,80,12,0xFF1C2833);draw_rect(164,442,24,12,0xFF27AE60);draw_rect(172,438,6,20,0xFFF1C40F);}else if(t==MG_HOLD){draw_rect(140,442,100,12,0xFF1C2833);draw_rect(140,442,55,12,0xFF3498DB);draw_rect(190,438,4,20,0xFFF1C40F);}else if(t==MG_COUNT){draw_circle(150,448,6,0xFFFFFFFF,8);draw_circle(170,448,6,0xFFFFFFFF,8);draw_circle(190,448,6,0xFFFFFFFF,8);draw_rect(230,440,20,16,0xFF9B59B6);}else if(t==MG_AVOID){draw_rect(140,440,40,16,0xFFE74C3C);draw_rect(200,440,40,16,0xFF2ECC71);}else if(t==MG_ZONE){draw_rect(140,442,100,12,0xFF1C2833);draw_rect(170,442,30,12,0xFF27AE60);draw_rect(180,438,6,20,0xFFF1C40F);}else{draw_rect(140,440,40,16,0xFF7F8C8D);draw_rect(200,440,40,16,0xFF2ECC71);}}
static void draw_mg_intro(GameContext *g){float pulse=0.5f+0.5f*sinf(g->anim_t*6);u32 c=0xFFE74C3C;if(g->mg_type==MG_MASH)c=0xFF2ECC71;else if(g->mg_type==MG_TIMING)c=0xFFF1C40F;else if(g->mg_type==MG_HOLD)c=0xFF3498DB;else if(g->mg_type==MG_COUNT)c=0xFF9B59B6;else if(g->mg_type==MG_AVOID)c=0xFFE74C3C;else if(g->mg_type==MG_ZONE)c=0xFF1ABC9C;draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_rect(140,100,568,280,0xFF1A0A2E);draw_rect(160,120,528,240,0xFF2C1A4A);draw_rect(200,180,448,36,c);draw_rect(200,180,(int)(448*pulse),36,0x55FFFFFF);draw_howto_bar(g->mg_type);draw_character(250,320,0,1,fabsf(sinf(g->anim_t*5))*8,(int)g->frame,1);draw_character(370,320,1,1,fabsf(sinf(g->anim_t*5+1))*8,(int)g->frame,1);draw_character(490,320,2,1,fabsf(sinf(g->anim_t*5+2))*8,(int)g->frame,1);draw_character(610,320,3,1,fabsf(sinf(g->anim_t*5+3))*8,(int)g->frame,1);}
static void draw_mg_play(GameContext *g){draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_rect(100,70,648,370,0xFF162033);draw_howto_bar(g->mg_type);if(g->mg_type==MG_MASH){float h=g->mg_meter*250;draw_rect(380,110,80,260,0xFF1C2833);draw_rect(385,365-h,70,h,0xFF2ECC71);draw_rect(385,365-h,70,6,0x66FFFFFF);{float t=1.f-(float)g->mg_timer/100.f;if(t<0)t=0;draw_rect(200,410,448*t,10,0xFFE74C3C);}}else if(g->mg_type==MG_TIMING){draw_rect(200,230,448,44,0xFF1C2833);draw_rect(200+448*0.42f,230,448*0.16f,44,0xFF27AE60);{float mx=200+g->mg_marker*448;draw_rect(mx-5,222,10,60,0xFFF1C40F);draw_rect(mx-5,222,10,4,0xFFFFFFFF);}}else if(g->mg_type==MG_HOLD){float h=g->mg_meter*250;draw_rect(380,110,80,260,0xFF1C2833);draw_rect(385,365-h,70,h,0xFF3498DB);{float ty=365.f-(float)g->mg_target/(float)(g->mg_target+25)*250.f;draw_rect(375,ty-3,90,6,0xFFF1C40F);}}else if(g->mg_type==MG_COUNT){if(g->mg_phase==0){if(g->mg_flash_count>0){float pulse=0.6f+0.4f*sinf(g->anim_t*25);draw_circle(424,220,40*pulse,0xFFFFFFFF,12);}draw_number(400,300,g->mg_flash_count,5,0xFF9B59B6);}else{draw_rect(300,180,248,100,0xFF2C1A4A);draw_number(400,210,(int)g->mg_meter,5,0xFF9B59B6);draw_rect(360,300,40,24,0xFF9B59B6);}}else if(g->mg_type==MG_AVOID){if(g->mg_phase==0)draw_rect(280,170,288,140,0xFFE74C3C);else{float pulse=0.7f+0.3f*sinf(g->anim_t*18);draw_rect(280,170,288,140,0xFF2ECC71);draw_rect(300,190,248*pulse,100,0x66FFFFFF);}}else if(g->mg_type==MG_ZONE){draw_rect(200,230,448,44,0xFF1C2833);{float zc=200+g->mg_zone_c*448,zw=g->mg_zone_w*448;draw_rect(zc-zw,230,zw*2,44,0xFF27AE60);}{float mx=200+g->mg_marker*448;draw_rect(mx-5,222,10,60,0xFFF1C40F);}{float t=(float)g->mg_zone_hits/140.f;if(t>1)t=1;draw_rect(200,410,448*t,10,0xFF1ABC9C);}}else{if(g->mg_timer<g->mg_go_at)draw_rect(300,190,248,100,0xFF7F8C8D);else{float pulse=0.7f+0.3f*sinf(g->anim_t*20);draw_rect(280,170,288,140,0xFF2ECC71);draw_rect(300,190,248*pulse,100,0x66FFFFFF);}}}
static void draw_mg_result(GameContext *g){int i;draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_rect(160,100,528,300,0xFF1A0A2E);draw_rect(180,120,488,260,0xFF2C1A4A);for(i=0;i<g->player_count;++i){int rank=g->players[i].mg_rank;float bx=220.f+rank*120.f;float bob=(rank==0)?fabsf(sinf(g->anim_t*6))*12:0;draw_character(bx,280-bob,g->players[i].color,1,bob,(int)g->frame,1);draw_number(bx-10,310,g->contest_rewards[i],3.5f,0xFF2ECC71);draw_number(bx-6,200,rank+1,4,0xFFF1C40F);}}
void game_render(GameContext *g){tiny3d_Clear(0xFF0B1320,TINY3D_CLEAR_ALL);tiny3d_AlphaTest(1,0x10,TINY3D_ALPHA_FUNC_GEQUAL);tiny3d_BlendFunc(1,(blend_src_func)(TINY3D_BLEND_FUNC_SRC_RGB_SRC_ALPHA|TINY3D_BLEND_FUNC_SRC_ALPHA_SRC_ALPHA),(blend_dst_func)(TINY3D_BLEND_FUNC_DST_RGB_ONE_MINUS_SRC_ALPHA|TINY3D_BLEND_FUNC_DST_ALPHA_ZERO),(blend_func)(TINY3D_BLEND_RGB_FUNC_ADD|TINY3D_BLEND_ALPHA_FUNC_ADD));tiny3d_Project2D();switch(g->state){case STATE_TITLE:draw_title(g);break;case STATE_SETUP:case STATE_BOARD_SELECT:draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_board(g);draw_tokens(g);draw_rect(200,460,448,20,0xFF2C3E50);if(g->team_mode)draw_rect(200,440,120,14,0xFFE67E22);if(((int)(g->anim_t*3))&1)draw_rect(220,465,408,10,0xFF3498DB);break;case STATE_TURN_START:case STATE_ITEM:case STATE_DICE_ROLL:case STATE_MOVE:case STATE_BRANCH:case STATE_LAND:case STATE_SHOP:case STATE_ROUND_END:draw_rect(0,0,SCR_W,SCR_H,0xFF0B1320);draw_board(g);draw_tokens(g);draw_fx(g);draw_hud(g);draw_dice(g);draw_popup(g);if(g->state==STATE_ITEM)draw_item_panel(g);if(g->state==STATE_SHOP)draw_shop_panel(g);if(g->state==STATE_BRANCH)draw_rect(300,60,248,16,0xFFF1C40F);break;case STATE_MG_INTRO:draw_mg_intro(g);draw_fx(g);break;case STATE_MG_PLAY:draw_mg_play(g);draw_fx(g);break;case STATE_MG_RESULT:draw_mg_result(g);draw_fx(g);break;case STATE_RESULTS:draw_results(g);break;default:break;}tiny3d_Flip();}
